        ["Prediction Y"] = "silent",
        ["Shot Camera Swap"] = "silent",
        ["Random Camera Zoom"] = "silent",
        ["Knock Check"] = "silent",

        -- compatibility with older labels
        ["HitPart (16 Parts)"] = "silent",
