            local function characterPosition(char)
                if not char then return nil end
                local root=char:FindFirstChild("HumanoidRootPart")
                    or char:FindFirstChild("UpperTorso")
                    or char:FindFirstChild("Torso")
                    or char:FindFirstChild("Head")
                if root and root:IsA("BasePart") then
                    return root.Position+Vector3.new(0,.7,0)
                end
                return nil
            end

            local function heartFacingCFrame(pos,roll)
                local cam=workspace.CurrentCamera
                roll=math.rad(roll or 0)

                if cam then
                    local cameraPos=cam.CFrame.Position
                    local flatTarget=Vector3.new(cameraPos.X,pos.Y,cameraPos.Z)

                    if (flatTarget-pos).Magnitude>.05 then
                        -- Keep the heart upright and facing the camera instead of
                        -- randomly turning it edge-on.
                        return CFrame.lookAt(pos,flatTarget)
                            * CFrame.Angles(0,math.pi,roll)
                    end
                end

                return CFrame.new(pos)*CFrame.Angles(0,0,roll)
            end

